-- create "analysis_jobs" table
CREATE TABLE "analysis_jobs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 81604378624), "job_type" character varying NOT NULL, "target_type" character varying NOT NULL, "target_id" character varying NOT NULL, "status" character varying NOT NULL, "steps_json" character varying NOT NULL DEFAULT '[]', "request_json" character varying NOT NULL DEFAULT '{}', "result_json" character varying NOT NULL DEFAULT '{}', "last_error" character varying NOT NULL DEFAULT '', "attempts" bigint NOT NULL DEFAULT 0, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "started_at" timestamptz NULL, "finished_at" timestamptz NULL, PRIMARY KEY ("id"));
-- create index "analysisjob_status_updated_at" to table: "analysis_jobs"
CREATE INDEX "analysisjob_status_updated_at" ON "analysis_jobs" ("status", "updated_at");
-- create index "analysisjob_target_type_target_id_created_at" to table: "analysis_jobs"
CREATE INDEX "analysisjob_target_type_target_id_created_at" ON "analysis_jobs" ("target_type", "target_id", "created_at");
-- create "analysis_runs" table
CREATE TABLE "analysis_runs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 85899345920), "trace_id" character varying NOT NULL DEFAULT '', "session_id" character varying NOT NULL DEFAULT '', "kind" character varying NOT NULL, "analyzer" character varying NOT NULL, "analyzer_version" character varying NOT NULL, "model" character varying NOT NULL DEFAULT '', "input_ref" character varying NOT NULL DEFAULT '', "output_json" character varying NOT NULL DEFAULT '{}', "status" character varying NOT NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "analysisrun_session_id_kind_created_at" to table: "analysis_runs"
CREATE INDEX "analysisrun_session_id_kind_created_at" ON "analysis_runs" ("session_id", "kind", "created_at");
-- create index "analysisrun_trace_id_kind_created_at" to table: "analysis_runs"
CREATE INDEX "analysisrun_trace_id_kind_created_at" ON "analysis_runs" ("trace_id", "kind", "created_at");
-- create "parse_jobs" table
CREATE TABLE "parse_jobs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 90194313216), "trace_id" character varying NOT NULL, "status" character varying NOT NULL, "attempts" bigint NOT NULL DEFAULT 0, "last_error" character varying NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "parsejob_status_updated_at" to table: "parse_jobs"
CREATE INDEX "parsejob_status_updated_at" ON "parse_jobs" ("status", "updated_at");
-- create "parser_versions" table
CREATE TABLE "parser_versions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 94489280512), "parser" character varying NOT NULL, "version" character varying NOT NULL, "description" character varying NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "parserversion_parser_version" to table: "parser_versions"
CREATE UNIQUE INDEX "parserversion_parser_version" ON "parser_versions" ("parser", "version");
-- create "semantic_nodes" table
CREATE TABLE "semantic_nodes" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 98784247808), "trace_id" character varying NOT NULL, "node_id" character varying NOT NULL, "parent_node_id" character varying NOT NULL DEFAULT '', "provider_type" character varying NOT NULL DEFAULT '', "normalized_type" character varying NOT NULL DEFAULT '', "role" character varying NOT NULL DEFAULT '', "path" character varying NOT NULL DEFAULT '', "node_index" bigint NOT NULL DEFAULT 0, "depth" bigint NOT NULL DEFAULT 0, "text_preview" character varying NOT NULL DEFAULT '', "json" character varying NOT NULL DEFAULT '', "raw" character varying NOT NULL DEFAULT '', "raw_ref" character varying NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "semanticnode_trace_id_depth_node_index" to table: "semantic_nodes"
CREATE INDEX "semanticnode_trace_id_depth_node_index" ON "semantic_nodes" ("trace_id", "depth", "node_index");
-- create index "semanticnode_trace_id_node_id" to table: "semantic_nodes"
CREATE UNIQUE INDEX "semanticnode_trace_id_node_id" ON "semantic_nodes" ("trace_id", "node_id");
-- create "system_events" table
CREATE TABLE "system_events" ("id" character varying NOT NULL, "fingerprint" character varying NOT NULL, "source" character varying NOT NULL, "category" character varying NOT NULL, "severity" character varying NOT NULL, "status" character varying NOT NULL, "title" character varying NOT NULL DEFAULT '', "message" character varying NOT NULL DEFAULT '', "details_json" character varying NOT NULL DEFAULT '{}', "trace_id" character varying NOT NULL DEFAULT '', "session_id" character varying NOT NULL DEFAULT '', "job_id" character varying NOT NULL DEFAULT '', "upstream_id" character varying NOT NULL DEFAULT '', "model" character varying NOT NULL DEFAULT '', "occurrence_count" bigint NOT NULL DEFAULT 1, "first_seen_at" timestamptz NOT NULL, "last_seen_at" timestamptz NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "read_at" timestamptz NULL, "resolved_at" timestamptz NULL, PRIMARY KEY ("id"));
-- create index "system_events_fingerprint_key" to table: "system_events"
CREATE UNIQUE INDEX "system_events_fingerprint_key" ON "system_events" ("fingerprint");
-- create index "systemevent_source_category_last_seen_at" to table: "system_events"
CREATE INDEX "systemevent_source_category_last_seen_at" ON "system_events" ("source", "category", "last_seen_at");
-- create index "systemevent_status_last_seen_at" to table: "system_events"
CREATE INDEX "systemevent_status_last_seen_at" ON "system_events" ("status", "last_seen_at");
-- create index "systemevent_trace_id_last_seen_at" to table: "system_events"
CREATE INDEX "systemevent_trace_id_last_seen_at" ON "system_events" ("trace_id", "last_seen_at");
-- create "trace_findings" table
CREATE TABLE "trace_findings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 107374182400), "trace_id" character varying NOT NULL, "finding_id" character varying NOT NULL, "category" character varying NOT NULL, "severity" character varying NOT NULL, "confidence" double precision NOT NULL DEFAULT 0, "title" character varying NOT NULL DEFAULT '', "description" character varying NOT NULL DEFAULT '', "evidence_path" character varying NOT NULL DEFAULT '', "evidence_excerpt" character varying NOT NULL DEFAULT '', "node_id" character varying NOT NULL DEFAULT '', "detector" character varying NOT NULL, "detector_version" character varying NOT NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "tracefinding_trace_id_finding_id" to table: "trace_findings"
CREATE UNIQUE INDEX "tracefinding_trace_id_finding_id" ON "trace_findings" ("trace_id", "finding_id");
-- create index "tracefinding_trace_id_severity_category" to table: "trace_findings"
CREATE INDEX "tracefinding_trace_id_severity_category" ON "trace_findings" ("trace_id", "severity", "category");
-- create "trace_observations" table
CREATE TABLE "trace_observations" ("trace_id" character varying NOT NULL, "parser" character varying NOT NULL, "parser_version" character varying NOT NULL, "status" character varying NOT NULL, "provider" character varying NOT NULL DEFAULT '', "operation" character varying NOT NULL DEFAULT '', "model" character varying NOT NULL DEFAULT '', "summary_json" character varying NOT NULL DEFAULT '{}', "warnings_json" character varying NOT NULL DEFAULT '[]', "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("trace_id"));
-- create index "traceobservation_status_updated_at" to table: "trace_observations"
CREATE INDEX "traceobservation_status_updated_at" ON "trace_observations" ("status", "updated_at");
